import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axiosInstance from '../axiosConfig';

const TABS = [
  { key: 'pending', label: 'Pending Booking' },
  { key: 'scheduled', label: 'Scheduled Booking' },
  { key: 'history', label: 'History Booking' },
];

const statusMatchesTab = (booking, tab) => {
  if (tab === 'pending') return booking.status === 'pending';
  if (tab === 'scheduled') return booking.status === 'confirmed';
  return booking.status === 'completed' || booking.status === 'cancelled';
};

const formatDate = (value) => {
  if (!value) return '—';
  return new Date(value).toLocaleDateString();
};

const formatInventoryItems = (booking) => {
  const listedItems =
    booking.inventoryItems?.map((item) =>
      typeof item === 'string' ? item : item.itemName
    ) || [];

  const customItems = booking.customItems || [];

  const allItems = [...listedItems, ...customItems];

  return allItems.length > 0 ? allItems.join(', ') : 'No items selected';
};

const AdminBooking = () => {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [bookings, setBookings] = useState([]);
  const [activeTab, setActiveTab] = useState('pending');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBookings = async () => {
      if (!user?.isAdmin) return;

      setLoading(true);

      try {
        const response = await axiosInstance.get('/api/bookings/admin/all');
        setBookings(response.data);
      } catch (error) {
        alert('Failed to fetch bookings.');
      } finally {
        setLoading(false);
      }
    };

    fetchBookings();
  }, [user]);

  const filteredBookings = useMemo(
    () => bookings.filter((booking) => statusMatchesTab(booking, activeTab)),
    [bookings, activeTab]
  );

  const handleManage = (booking) => {
    navigate('/admin/bookings/manage', { state: { booking } });
  };

  if (!user?.isAdmin) {
    return (
      <div className="min-h-screen bg-[#D7EFFF] flex items-center justify-center p-6 text-center">
        <div className="bg-white/90 rounded-2xl shadow-xl p-10 max-w-lg">
          <h1 className="text-2xl font-semibold text-[#0d2440] mb-4">
            Admin Only
          </h1>

          <p className="text-[#546b86] mb-6">
            This page is restricted to admin accounts. Please log in with admin credentials.
          </p>

          <button
            onClick={() => navigate('/admin')}
            className="px-6 py-3 rounded-full bg-[#142C3E] text-white font-semibold hover:bg-[#0f1b2c]"
          >
            Go to Admin Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#D7EFFF] px-6 py-10">
      <div className="max-w-6xl mx-auto">
        <div className="flex flex-wrap gap-4 mb-8">
          {TABS.map((tab) => (
            <button
              key={tab.key}
              className={`px-6 py-2 rounded-full font-semibold transition drop-shadow-lg ${
                activeTab === tab.key
                  ? 'bg-[#93A9C0] text-black'
                  : 'bg-[#142C3E] text-white'
              }`}
              onClick={() => setActiveTab(tab.key)}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {loading ? (
          <p className="text-center text-black">Loading bookings...</p>
        ) : filteredBookings.length === 0 ? (
          <p className="text-center text-black">
            There is no booking for this category.
          </p>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredBookings.map((booking) => (
              <div
                key={booking._id}
                className="bg-white/90 rounded-3xl shadow-xl border border-[#c8e1fb] p-6 space-y-3"
              >
                <div className="flex justify-between items-start gap-4">
                  <div>
                    <h2 className="text-2xl font-semibold text-[#0d2440]">
                      {booking.serviceType}
                    </h2>

                    <p className="text-sm text-[#546b86] capitalize">
                      Status: {booking.status}
                    </p>
                  </div>

                  <span className="px-4 py-1 rounded-full bg-[#C1D8F0] text-[#0d2440] font-semibold capitalize">
                    {booking.status}
                  </span>
                </div>

                <div className="space-y-2 text-[#0d2440]">
                  <p>
                    <strong>Customer:</strong>{' '}
                    {booking.user?.name || 'Unknown'}
                  </p>

                  <p>
                    <strong>Email:</strong>{' '}
                    {booking.user?.email || '—'}
                  </p>

                  <p>
                    <strong>Phone:</strong>{' '}
                    {booking.user?.phone || '—'}
                  </p>

                  <p>
                    <strong>Property Type:</strong>{' '}
                    {booking.propertyType || '—'}
                  </p>

                  <p>
                    <strong>Pick Up Address:</strong>{' '}
                    {booking.pickupAddress || '—'}
                  </p>

                  <p>
                    <strong>Destination Address:</strong>{' '}
                    {booking.destinationAddress || '—'}
                  </p>

                  <p>
                    <strong>Date:</strong> {formatDate(booking.date)}
                  </p>

                  <p>
                    <strong>Time:</strong> {booking.time || '—'}
                  </p>

                  <p>
                    <strong>Inventory Items:</strong>{' '}
                    {formatInventoryItems(booking)}
                  </p>

                  <p>
                    <strong>Remark:</strong> {booking.remarks || '—'}
                  </p>

                  {booking.assignedStaff && booking.assignedStaff.length > 0 && (
                    <p>
                      <strong>Assigned Staff:</strong>{' '}
                      {booking.assignedStaff
                        .map((staff) =>
                          typeof staff === 'string' ? staff : staff.name
                        )
                        .join(', ')}
                    </p>
                  )}
                </div>

                <div className="flex justify-end pt-4">
                  <button
                    onClick={() => handleManage(booking)}
                    className="px-6 py-2 rounded-full bg-[#142C3E] text-white font-semibold hover:bg-[#0f1b2c] transition"
                  >
                    Manage
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminBooking;
